<script>
import BrowserViewer from './BrowserViewer.vue'
import DesktopViewer from './DesktopViewer.vue'
import Chat from '@/components/chat/Chat.vue'
import ConfirmDialog from '../ConfirmDialog.vue'
import VerticalSplitter from '../layout/VerticalSplitter.vue'
import { SESSION_LABELS, label } from '@/utils/sessionLabels'

export default {
  name: 'BrowserSessionPanel',
  components: { BrowserViewer, DesktopViewer, Chat, ConfirmDialog, VerticalSplitter },
  props: {
    // Present when the panel is rendered inside a meeting call. It enables
    // collaborative annotations and the "share with call" action.
    meetId: { type: String, default: null }
  },
  data() {
    return {
      editFormData: {},
      saving: false,
      showChat: false,
      chatLoading: false,
      browserChatId: null,
      showChatMenu: false,
      showChatPicker: false,
      pickerLoading: false,
      pickerChats: [],
      pickerSearch: '',
      pickerError: null,
      // Why the selector was opened instead of a chat (no linked chat, stale
      // link, backend error). Rendered inside the dialog so the user is never
      // left wondering why a click did not open a chat.
      pickerReason: null,
      showDeleteConfirm: false,
      deleting: false
    }
  },
  computed: {
    // Section/item names of the concept live in utils/sessionLabels.js
    sessionLabels() {
      return SESSION_LABELS
    },
    deleteConfirmMessage() {
      return label('deleteConfirm', { name: this.selectedSession?.name || SESSION_LABELS.untitled })
    },
    selectedSession() {
      return this.$storex.browsers.selectedSession
    },
    selectedSessionId() {
      return this.selectedSession?.id || null
    },
    editingSessionId() {
      return this.$storex.browsers.editingSessionId
    },
    isEditing() {
      return this.editingSessionId !== null
    },
    isMobile() {
      return this.$storex.ui.isMobile
    },
    isBrowserSession() {
      return (this.selectedSession?.kind || 'browser') === 'browser'
    },
    isVmSession() {
      return ['windows', 'macos'].includes(this.selectedSession?.kind)
    },
    isRemoteSession() {
      return this.selectedSession?.kind === 'remote'
    },
    chatLabel() {
      const chats = this.selectedSession?.chat_ids || []
      return chats.length ? `${chats.length} chat(s)` : 'No chat linked'
    },
    browserChat() {
      return this.browserChatId ? this.$storex.chats.chats[this.browserChatId] : null
    },
    browserChatHasTools() {
      return (this.browserChat?.profiles || []).some(p => p === 'browser' || p === 'computer')
    },
    linkedChatIds() {
      return this.selectedSession?.chat_ids || []
    },
    linkedChats() {
      return this.linkedChatIds.map((id) => {
        const chat = this.pickerChats.find(item => item.id === id) ||
          this.$storex.chats.chats[id]
        return chat || { id, name: `Chat ${String(id).slice(0, 8)}` }
      })
    },
    // Chats of this session, most recent FIRST by last updated message. This is
    // both what the header switcher lists and where the chat opened by default
    // comes from: "latest" means the chat whose last message is the newest.
    linkedChatOptions() {
      return this.linkedChatIds
        .map((id, index) => {
          const chat = this.chatMetaById(id)
          const stamp = this.chatLastMessageAt(chat)
          return {
            id,
            index,
            name: chat?.name || `Chat ${String(id).slice(0, 8)}`,
            updatedLabel: this.formatChatDate(stamp),
            time: this.chatTimestamp(stamp)
          }
        })
        // Chats without a known message keep the session order: the backend
        // appends every chat it links, so the newest id comes last.
        .sort((a, b) => (b.time - a.time) || (b.index - a.index))
    },
    latestLinkedChatId() {
      return this.linkedChatOptions[0]?.id || null
    },
    activeChatLabel() {
      const chat = this.browserChat
      if (chat) return chat.name || 'Untitled chat'
      return this.chatLoading ? 'Opening chat…' : 'Chat with this computer'
    },
    filteredPickerChats() {
      const term = (this.pickerSearch || '').trim().toLowerCase()
      const matches = term
        ? this.pickerChats.filter(chat =>
            String(chat.name || '').toLowerCase().includes(term) ||
            String(chat.description || '').toLowerCase().includes(term)
          )
        : this.pickerChats
      // The list can contain thousands of chats; render a bounded slice.
      return matches.slice(0, 100)
    }
  },
  watch: {
    editingSessionId: {
      immediate: true,
      handler(newId) {
        if (newId) {
          const session = this.$storex.browsers.sessionById(newId)
          if (session) {
            this.editFormData = {
              id: session.id,
              name: session.name,
              image: session.image || '',
              cpu_cores: session.cpu_cores || '',
              ram_size: session.ram_size || '',
              disk_size: session.disk_size || '',
              shm_size: session.shm_size || '',
              env: this.formatEnv(session.extra_env),
              desktop_width: session.desktop_width || '',
              desktop_height: session.desktop_height || ''
            }
          }
        } else {
          this.editFormData = {}
        }
      }
    },
    selectedSessionId(newId, oldId) {
      if (newId === oldId) return
      this.showChat = false
      this.showChatMenu = false
      this.showChatPicker = false
      this.pickerReason = null
      // A pending confirmation belongs to the session that opened it
      this.showDeleteConfirm = false
      this.browserChatId = null
    }
  },
  methods: {
    /** Render the extra image env object as KEY=VALUE lines. */
    formatEnv(env) {
      if (!env || typeof env !== 'object') return ''
      return Object.keys(env)
        .sort()
        .map(key => `${key}=${env[key]}`)
        .join('\n')
    },
    /** Parse the KEY=VALUE textarea (comments/blank lines ignored). */
    parseEnvText(text) {
      const env = {}
      String(text || '').split('\n').forEach((raw, index) => {
        const line = raw.trim()
        if (!line || line.startsWith('#')) return
        const separator = line.indexOf('=')
        if (separator <= 0) {
          throw new Error(`Environment variable on line ${index + 1} must use KEY=VALUE`)
        }
        const key = line.slice(0, separator).trim()
        if (!/^[A-Za-z_][A-Za-z0-9_]*$/.test(key)) {
          throw new Error(`Invalid environment variable name '${key}' (line ${index + 1})`)
        }
        env[key] = line.slice(separator + 1).trim()
      })
      return env
    },
    /** Validate the advanced fields; returns a message or null. */
    validateAdvancedSettings() {
      if (this.isRemoteSession) return null
      const sizePattern = /^\d+(?:\.\d+)?\s*[KMGT](?:i?b)?$/i
      const sizeError = (label, value, example) => {
        const text = String(value || '').trim()
        if (!text) return null
        return sizePattern.test(text)
          ? null
          : `${label} must be a number with a unit, for example ${example}.`
      }
      const errors = [
        sizeError('RAM', this.editFormData.ram_size, '8G'),
        sizeError('Disk size', this.isVmSession ? this.editFormData.disk_size : '', '128G'),
        sizeError('Shared memory', this.isVmSession ? '' : this.editFormData.shm_size, '2G')
      ].filter(Boolean)
      if (errors.length) return errors[0]

      if (this.editFormData.cpu_cores) {
        const cpus = Number(this.editFormData.cpu_cores)
        if (!Number.isInteger(cpus) || cpus < 1 || cpus > 128) {
          return 'vCPUs must be a whole number between 1 and 128.'
        }
      }
      if (!this.isVmSession) {
        const width = Number(this.editFormData.desktop_width)
        const height = Number(this.editFormData.desktop_height)
        if (this.editFormData.desktop_width && (!Number.isInteger(width) || width < 640 || width > 7680)) {
          return 'Desktop width must be a whole number between 640 and 7680.'
        }
        if (this.editFormData.desktop_height && (!Number.isInteger(height) || height < 480 || height > 4320)) {
          return 'Desktop height must be a whole number between 480 and 4320.'
        }
      }
      let env = {}
      try {
        env = this.parseEnvText(this.editFormData.env)
      } catch (error) {
        return error.message
      }
      if (Object.keys(env).length > 50) return 'Use at most 50 environment variables.'
      return null
    },
    /** Advanced fields sent to the update endpoint. */
    advancedPayload() {
      if (this.isRemoteSession) return {}
      return {
        image: (this.editFormData.image || '').trim() || null,
        cpu_cores: Number(this.editFormData.cpu_cores) || null,
        ram_size: (this.editFormData.ram_size || '').trim() || null,
        disk_size: this.isVmSession
          ? ((this.editFormData.disk_size || '').trim() || null)
          : null,
        shm_size: this.isVmSession
          ? null
          : ((this.editFormData.shm_size || '').trim() || null),
        extra_env: this.parseEnvText(this.editFormData.env),
        desktop_width: this.isVmSession
          ? null
          : (Number(this.editFormData.desktop_width) || null),
        desktop_height: this.isVmSession
          ? null
          : (Number(this.editFormData.desktop_height) || null)
      }
    },
    async handleSaveSession(restart = false) {
      if (!this.editFormData.name?.trim()) {
        this.$storex.ui.addNotification({
          text: 'Session name is required',
          type: 'warning'
        })
        return
      }
      const validationError = this.validateAdvancedSettings()
      if (validationError) {
        this.$storex.ui.addNotification({ text: validationError, type: 'warning' })
        return
      }

      const sessionId = this.editFormData.id
      const isContainerSession = !this.isRemoteSession
      this.saving = true
      try {
        const payload = {
          id: sessionId,
          name: this.editFormData.name,
          ...this.advancedPayload()
        }
        await this.$storex.browsers.updateSession(payload)
        if (restart && isContainerSession) {
          await this.$storex.browsers.restartSession(sessionId)
        } else if (isContainerSession) {
          this.$storex.ui.addNotification({
            text: 'Settings saved. Restart the session to apply resource changes.',
            type: 'info'
          })
        }
      } catch (error) {
        console.error('Failed to save session:', error)
      } finally {
        this.saving = false
      }
    },
    handleCancelEdit() {
      this.$storex.browsers.stopEditingSession()
      this.editFormData = {}
    },
    startEditingSession() {
      if (this.selectedSession?.id) {
        this.$storex.browsers.startEditingSession(this.selectedSession.id)
      }
    },
    handleDeleteSession() {
      if (!this.selectedSession?.id) return
      // Destructive: never delete on a single click, ask in a modal first
      this.showDeleteConfirm = true
    },
    cancelDelete() {
      if (this.deleting) return
      this.showDeleteConfirm = false
    },
    async confirmDeleteSession() {
      const sessionId = this.selectedSession?.id
      if (!sessionId || this.deleting) return

      this.deleting = true
      try {
        await this.$storex.browsers.deleteSession(sessionId)
        this.showDeleteConfirm = false
      } catch (error) {
        console.error('Failed to delete session:', error)
      } finally {
        this.deleting = false
      }
    },
    async handleRestartSession() {
      if (!this.selectedSession?.id) return
      try {
        await this.$storex.browsers.restartSession(this.selectedSession.id)
      } catch (error) {
        console.error('Failed to restart session:', error)
      }
    },
    // ── Chat switching ─────────────────────────────────────────────────────

    /** Metadata of a chat: fetched index first, then the store cache. */
    chatMetaById(chatId) {
      if (!chatId) return null
      return this.pickerChats.find(chat => chat.id === chatId) ||
        this.$storex.chats.chats[chatId] ||
        null
    },
    /** Timestamp as a number, 0 when missing/unparseable (so sorting is stable). */
    chatTimestamp(stamp) {
      if (!stamp) return 0
      const time = new Date(stamp).getTime()
      return Number.isNaN(time) ? 0 : time
    },
    /**
     * Stamp of the chat's last UPDATED message — what "latest" is measured on.
     * A full chat carries every message, a list/search summary only carries the
     * last one, so the newest message wins in both cases. Edited messages are
     * taken into account through their `updated_at`.
     */
    chatLastMessageAt(chat) {
      if (!chat) return null
      const messages = Array.isArray(chat.messages) ? chat.messages : []
      let latestStamp = null
      let latestTime = 0
      messages.forEach((message) => {
        const stamp = message?.updated_at || message?.timestamp || message?.created_at
        const time = this.chatTimestamp(stamp)
        if (time > latestTime) {
          latestTime = time
          latestStamp = stamp
        }
      })
      if (latestStamp) return latestStamp
      // Chat without messages loaded: fall back to its own bookkeeping fields.
      return chat.lastMessageAt || chat.updated_at || chat.created_at || null
    },
    /**
     * Id of the chat with the last updated message. Null when the session has
     * no chat linked (or none of them could be resolved), so the caller opens
     * the chat selector instead of letting the backend invent a chat.
     */
    async resolveLatestChatId() {
      const ids = [...this.linkedChatIds]
      if (!ids.length) return null
      // Ranking (and the switcher labels) need the metadata of every linked
      // chat. The store only holds the chats already opened here, so the index
      // is fetched once when any of them is still unknown.
      if (ids.some(id => !this.chatMetaById(id))) {
        await this.loadPickerChats()
      }
      return this.latestLinkedChatId
    },
    /**
     * Footer "Chat": dock the pane with the chat holding the last updated
     * message (focusing it when already open). When no chat can be resolved the
     * selector opens, so the user picks one or creates it — never a silent one.
     */
    async openLatestChat() {
      if (!this.selectedSession?.id || this.chatLoading) return
      if (this.showChat && this.browserChatId && !this.isMobile) {
        this.focusChat()
        return
      }
      await this.openChatWith({ latest: true })
    },
    focusChat() {
      this.showChat = true
      this.$nextTick(() => {
        // The composer is the only textarea the docked chat renders.
        const input = this.$refs.chatPane?.querySelector('textarea')
        if (input) input.focus()
      })
    },
    toggleChatMenu() {
      if (this.showChatMenu) {
        this.showChatMenu = false
        return
      }
      this.showChatMenu = true
      // The menu lists the session chats with their last-activity label, so the
      // metadata must be there before it is rendered.
      if (this.linkedChatIds.some(id => !this.chatMetaById(id))) {
        this.loadPickerChats()
      }
    },
    closeChatMenu() {
      this.showChatMenu = false
    },
    switchChat(chatId) {
      this.showChatMenu = false
      if (!chatId || chatId === this.browserChatId) {
        if (chatId) this.focusChat()
        return
      }
      this.openChatWith({ chatId })
    },
    newChatFromMenu() {
      this.showChatMenu = false
      this.createNewBrowserChat()
    },
    browseChatsFromMenu() {
      this.showChatMenu = false
      this.openChatPicker()
    },
    handleDocumentMousedown(event) {
      if (!this.showChatMenu) return
      const menu = this.$refs.chatMenu
      const title = this.$refs.chatMenuTrigger
      const switcher = this.$refs.chatSwitchTrigger
      if (menu?.contains(event.target) ||
          title?.contains(event.target) ||
          switcher?.contains(event.target)) return
      this.showChatMenu = false
    },
    handleWindowKeydown(event) {
      if (event.key === 'Escape' && this.showChatMenu) {
        this.showChatMenu = false
      }
    },

    // ── Chat picker / opening ──────────────────────────────────────────────

    /**
     * Open the chat selector.
     *
     * This is the single fallback for every "no chat could be opened" path: the
     * selector is the only place where the user can link an existing chat or
     * create a new one, so a failed click must always end here.
     */
    promptChatSelection(reason = null) {
      if (!this.selectedSession?.id) return
      this.pickerReason = reason
      this.showChat = false
      this.showChatPicker = true
      this.loadPickerChats()
    },
    openChatPicker() {
      if (!this.selectedSession?.id) return
      this.showChatMenu = false
      this.promptChatSelection()
    },
    closeChatPicker() {
      this.showChatPicker = false
      this.pickerReason = null
    },
    async loadPickerChats() {
      if (this.pickerLoading) return
      this.pickerLoading = true
      this.pickerError = null
      try {
        const project = this.$storex.projects.activeProject
        const api = project?.$api
        if (api?.chats?.list) {
          const response = await api.chats.list()
          const chats = Array.isArray(response) ? response : (response?.chats || [])
          // Same ordering rule as the switcher: newest last updated message first
          this.pickerChats = [...chats].sort((a, b) =>
            this.chatTimestamp(this.chatLastMessageAt(b)) -
            this.chatTimestamp(this.chatLastMessageAt(a))
          )
        } else {
          this.pickerChats = this.$storex.chats.allChats || []
        }
      } catch (error) {
        console.error('Failed to load chats for the picker:', error)
        this.pickerError = error.message || 'Could not load chats'
        this.pickerChats = this.$storex.chats.allChats || []
      } finally {
        this.pickerLoading = false
      }
    },
    /**
     * Open a chat in the docked pane.
     *
     * `latest` resolves the chat with the last updated message. The selector
     * opens whenever no chat can be opened — no linked chat, a linked chat that
     * was deleted (404) or a backend that returned nothing — so the user always
     * decides between an existing chat and a new one, and the button never
     * appears to do nothing.
     */
    async onAskAiAboutPage(context = {}) {
      if (!this.selectedSession?.id) return
      try {
        if (!this.showChat || !this.browserChatId) {
          await this.openChatWith({ latest: true })
        }
        if (!this.browserChatId) {
          // openChatWith opened the picker because no chat was linked.
          return
        }
        await this.$nextTick()
        const chat = this.$refs.browserChat
        if (!chat?.setEditorText) {
          this.$storex.ui.addNotification({
            text: 'Open the browser chat to ask the AI about this page',
            type: 'info'
          })
          return
        }
        const lines = [
          this.isBrowserSession
            ? 'I am looking at this page in the shared browser:'
            : 'I am looking at this shared computer screen:'
        ]
        if (context.url) lines.push(`URL: ${context.url}`)
        if (context.title) lines.push(`Title: ${context.title}`)
        if (context.selection) {
          lines.push(
            this.isBrowserSession
              ? `Selected text: "${String(context.selection).slice(0, 600)}"`
              : `Visible text (OCR):\n${String(context.selection).slice(0, 2000)}`
          )
        }
        if (context.active?.name || context.active?.text) {
          lines.push(`I was editing: ${context.active.name || context.active.text}`)
        }
        lines.push('', 'Please help me with: ')
        chat.setEditorText(lines.join('\n'))
        this.focusChat()
      } catch (error) {
        console.error('[BrowserSessionPanel] Could not prepare the AI question:', error)
        this.$storex.ui.addNotification({
          text: error.message || 'Could not prepare the question',
          type: 'error'
        })
      }
    },
    /**
     * Send the annotated browser screenshot.
     *
     * The board's "Send" action asks for two things: copy the PNG to the
     * clipboard, and — when a chat pane is open — post it as a NEW message
     * (not a composer draft) with the generated visual instructions.
     */
    async onSendAnnotations(payload = {}) {
      if (!payload?.dataUrl) return
      const copied = await this.copyAnnotatedImage(payload.dataUrl)
      const stamp = new Date().toISOString().replace(/[:.]/g, '-').slice(0, 19)
      const fileName = `browser-annotations-${stamp}.png`
      const chat = this.showChat ? this.$refs.browserChat : null

      if (chat?.sendAnnotatedMessage) {
        try {
          const sent = await chat.sendAnnotatedMessage({
            content: this.buildAnnotationPrompt(payload),
            dataUrl: payload.dataUrl,
            fileName
          })
          if (sent) {
            this.$storex.ui.addNotification({
              text: copied
                ? 'Annotated screenshot copied to the clipboard and sent to the chat.'
                : 'Annotated screenshot sent to the chat (clipboard copy was not available).',
              type: 'success'
            })
            return
          }
        } catch (error) {
          console.error('[BrowserSessionPanel] Could not send annotations:', error)
          this.$storex.ui.addNotification({
            text: error.message || 'Could not send the annotated screenshot to the chat',
            type: 'error'
          })
        }
      }

      if (copied) {
        this.$storex.ui.addNotification({
          text: 'Annotated screenshot copied to the clipboard. Open the chat to send it.',
          type: 'info'
        })
      } else {
        this.downloadAnnotations(payload)
      }
    },
    /** Prompt that accompanies the annotated screenshot in the chat. */
    buildAnnotationPrompt(payload = {}) {
      const lines = [
        'I annotated the shared browser page to give you visual instructions.',
        'The annotated screenshot is attached to this message.'
      ]
      if (payload.pageUrl) lines.push(`URL: ${payload.pageUrl}`)
      if (payload.pageTitle) lines.push(`Title: ${payload.pageTitle}`)
      if (['none', 'error'].includes(payload.captureKind)) {
        lines.push('(The live page screenshot could not be captured; rely on the URL and the notes below.)')
      }
      if (payload.summary) {
        lines.push('', 'What the drawing shows:', payload.summary)
      }
      lines.push(
        '',
        'Use the attached image together with these notes as the instructions for what to do on the page.'
      )
      return lines.join('\n')
    },
    /**
     * Copy the annotated PNG to the system clipboard.
     * The ClipboardItem is created inside the click task (before any await) so
     * browsers keep the user activation required by `clipboard.write`.
     */
    async copyAnnotatedImage(dataUrl) {
      try {
        const blob = this.dataUrlToBlob(dataUrl)
        if (!navigator.clipboard?.write || typeof ClipboardItem === 'undefined') {
          throw new Error('Clipboard image copy is not supported here')
        }
        await navigator.clipboard.write([
          new ClipboardItem({ 'image/png': blob })
        ])
        return true
      } catch (error) {
        console.warn('[BrowserSessionPanel] Could not copy annotations to clipboard:', error)
        return false
      }
    },
    /** Convert a data URL to a Blob without an async fetch (keeps activation). */
    dataUrlToBlob(dataUrl) {
      const comma = String(dataUrl).indexOf(',')
      if (comma < 0) throw new Error('Invalid annotated image data')
      const header = dataUrl.slice(0, comma)
      const base64 = dataUrl.slice(comma + 1)
      const mime = /data:([^;]+)/i.exec(header)?.[1] || 'image/png'
      const binary = atob(base64)
      const bytes = new Uint8Array(binary.length)
      for (let index = 0; index < binary.length; index += 1) {
        bytes[index] = binary.charCodeAt(index)
      }
      return new Blob([bytes], { type: mime })
    },
    downloadAnnotations(payload) {
      try {
        const link = document.createElement('a')
        const stamp = new Date().toISOString().replace(/[:.]/g, '-').slice(0, 19)
        link.href = payload.dataUrl
        link.download = `browser-annotations-${stamp}.png`
        document.body.appendChild(link)
        link.click()
        link.remove()
        this.$storex.ui.addNotification({
          text: 'Clipboard access is unavailable, so the annotated image was downloaded.',
          type: 'warning'
        })
      } catch (error) {
        this.$storex.ui.addNotification({
          text: error.message || 'Could not prepare the annotated image',
          type: 'error'
        })
      }
    },
    /**
     * Share the session with the meeting.
     *
     * The meet store persists it on the meet (so participants that join later
     * open the same session) and announces it over the WebRTC data channel for
     * the peers already connected.
     */
    async onShareSession(session = {}) {
      if (!this.meetId || !session.sessionId) return
      try {
        await this.$storex.meets.shareBrowserSession({
          meetId: this.meetId,
          session: {
            id: session.sessionId,
            name: session.name || this.selectedSession?.name || 'Browser session',
            kind: this.selectedSession?.kind || 'browser'
          }
        })
        this.$storex.ui.addNotification({
          text: `Browser session "${session.name || 'session'}" shared with the call`,
          type: 'success'
        })
      } catch (error) {
        console.error('[BrowserSessionPanel] Could not share the session', error)
        this.$storex.ui.addNotification({
          text: error.message || 'Could not share the session with the call',
          type: 'error'
        })
      }
    },

    async openChatWith({ chatId = null, createNew = false, latest = false } = {}) {
      if (!this.selectedSession?.id || this.chatLoading) return
      this.chatLoading = true
      try {
        const targetChatId = latest ? await this.resolveLatestChatId() : chatId

        if (!targetChatId && !createNew) {
          // No chat found → let the user choose
          this.promptChatSelection(
            this.linkedChatIds.length
              ? 'The chat linked to this session is no longer available.'
              : null
          )
          return
        }

        this.showChatPicker = false
        this.pickerReason = null
        const chat = await this.$storex.browsers.ensureChat({
          sessionId: this.selectedSession.id,
          chatId: targetChatId,
          createNew
        })

        if (!chat?.id) {
          // The backend returned no chat: offer the selection instead of
          // docking an empty pane the user cannot use.
          this.promptChatSelection('No chat could be opened for this session.')
          return
        }

        this.browserChatId = chat.id
        this.showChat = true
      } catch (error) {
        console.error('Failed to open browser chat:', error)
        // A linked chat that no longer exists must not be a dead end: fall back
        // to the selector, which is where the chat can be linked or created.
        const status = error?.response?.status
        this.promptChatSelection(
          status === 404
            ? 'That chat no longer exists. Pick another one or create a new chat.'
            : 'The chat could not be opened. Pick another one or create a new chat.'
        )
        this.$storex.ui.addNotification({
          text: error.message || 'Failed to open the browser chat',
          type: 'error'
        })
      } finally {
        this.chatLoading = false
      }
    },
    selectPickerChat(chat) {
      if (!chat?.id) return
      this.openChatWith({ chatId: chat.id })
    },
    createNewBrowserChat() {
      this.openChatWith({ createNew: true })
    },
    closeChat() {
      this.showChat = false
      this.showChatMenu = false
    },
    formatChatDate(value) {
      if (!value) return ''
      try {
        return new Date(value).toLocaleString()
      } catch (e) {
        return value
      }
    },
    formatDate(value) {
      if (!value) return ''
      try {
        return new Date(value).toLocaleString()
      } catch (e) {
        return value
      }
    }
  },
  mounted() {
    document.addEventListener('mousedown', this.handleDocumentMousedown)
    window.addEventListener('keydown', this.handleWindowKeydown)
  },
  beforeUnmount() {
    document.removeEventListener('mousedown', this.handleDocumentMousedown)
    window.removeEventListener('keydown', this.handleWindowKeydown)
  }
}
</script>

<template>
  <div class="flex flex-col h-full bg-base-100 overflow-hidden">
    <!-- Empty State -->
    <div v-if="!selectedSession && !isEditing" class="flex items-center justify-center h-full text-base-content/50">
      <div class="text-center">
        <i class="fa-solid fa-desktop text-4xl mb-3 block opacity-25"></i>
        <p class="text-sm">{{ sessionLabels.noSelection }}</p>
        <p class="text-xs opacity-60 mt-1">The AI and you control the same computer.</p>
      </div>
    </div>

    <!-- Edit Mode -->
    <div v-else-if="isEditing" class="flex flex-col h-full">
      <div class="sticky top-0 bg-base-100 border-b border-base-content/10 p-4">
        <h3 class="text-lg font-bold">Session settings</h3>
        <p class="text-xs opacity-60 mt-0.5">{{ selectedSession?.name }}</p>
      </div>
      <div class="p-4 space-y-4 flex-1 overflow-y-auto">
        <div class="form-control">
          <label class="label">
            <span class="label-text font-semibold">Session Name *</span>
          </label>
          <input
            v-model="editFormData.name"
            type="text"
            placeholder="Session name"
            class="input input-bordered input-sm"
            @keyup.enter="handleSaveSession(false)"
          />
        </div>

        <template v-if="!isRemoteSession">
          <div class="divider text-[10px] font-semibold uppercase tracking-wide opacity-50 my-1">
            Image and resources
          </div>

          <div class="grid grid-cols-2 gap-3">
            <div class="form-control">
              <label class="label py-1">
                <span class="label-text text-xs font-semibold">vCPUs</span>
              </label>
              <input
                v-model.number="editFormData.cpu_cores"
                type="number"
                min="1"
                max="128"
                step="1"
                class="input input-bordered input-sm w-full"
                :placeholder="isVmSession ? 'default (4)' : 'host default'"
              />
            </div>
            <div class="form-control">
              <label class="label py-1">
                <span class="label-text text-xs font-semibold">RAM</span>
              </label>
              <input
                v-model="editFormData.ram_size"
                type="text"
                class="input input-bordered input-sm w-full font-mono"
                :placeholder="isVmSession ? 'default (8G)' : 'e.g. 2G'"
                spellcheck="false"
              />
            </div>
            <div v-if="isVmSession" class="form-control">
              <label class="label py-1">
                <span class="label-text text-xs font-semibold">Disk size</span>
              </label>
              <input
                v-model="editFormData.disk_size"
                type="text"
                class="input input-bordered input-sm w-full font-mono"
                :placeholder="selectedSession?.kind === 'macos' ? 'default (128G)' : 'default (64G)'"
                spellcheck="false"
              />
            </div>
            <div v-else class="form-control">
              <label class="label py-1">
                <span class="label-text text-xs font-semibold">Shared memory</span>
              </label>
              <input
                v-model="editFormData.shm_size"
                type="text"
                class="input input-bordered input-sm w-full font-mono"
                placeholder="default (2G)"
                spellcheck="false"
              />
            </div>
          </div>

          <div v-if="isVmSession" class="flex flex-wrap items-center gap-1">
            <span class="text-[11px] opacity-60">Disk presets:</span>
            <button
