    }
  },
  mounted() {
    // Standalone dialog: ESC closes it. Embedded, the wizard owns dismissal.
    if (!this.embedded) window.addEventListener('keydown', this.onKeydown)
  },
  beforeUnmount() {
    if (this.searchTimer) window.clearTimeout(this.searchTimer)
